SELECT id, symbol, generated_at, latest_price, decision, market_regime, liquidity_status, btc_context_status, atr_at_signal FROM crypto_ai.trade_signal WHERE interval_code = '1m' AND ((symbol = 'EGLDUSDT' AND generated_at BETWEEN '2026-10-11 20:24:00' AND '2026-10-11 20:55:02') OR (symbol = 'EGLDUSDT' AND generated_at BETWEEN '2026-10-11 22:09:00' AND '2026-10-11 22:40:02') OR (symbol = 'XRPUSDT' AND generated_at BETWEEN '2026-10-12 02:04:00' AND '2026-10-12 02:35:02') OR (symbol = 'DOGEUSDT' AND generated_at BETWEEN '2026-10-12 03:31:00' AND '2026-10-12 04:02:03') OR (symbol = 'SHIBUSDT' AND generated_at BETWEEN '2026-10-12 06:05:00' AND '2026-10-12 06:36:02') OR (symbol = 'ACEUSDT' AND generated_at BETWEEN '2026-10-12 09:26:00' AND '2026-10-12 09:57:02')) ORDER BY symbol, generated_at LIMIT 240